// Builders for the polished spatial-question graphics (client-safe, pure string).
// Figures are drawn centred in a 120×120 viewBox so rotation/reflection options can
// be generated by REAL geometric transforms (rotate/scale/matrix about the centre),
// which makes those answers provably correct rather than hand-eyeballed.

const STROKE = '#00333A'
const TOP = '#A5DCE3'
const LEFT = '#5BB0BC'
const RIGHT = '#115F6B'
const FILL = '#177E8D'
const PAPER = '#F0FBFD'
const VB = 120
const C = VB / 2 // centre

function wrap(inner: string): string {
  return `<svg viewBox="0 0 ${VB} ${VB}" width="116" height="116" xmlns="http://www.w3.org/2000/svg">${inner}</svg>`
}

// ── Isometric 3D cube stacks ─────────────────────────────────────────────────
const TW = 13 // tile half-width
const TH = 6.5 // tile half-height (2:1 iso)
const CH = 15 // cube height

function cubeAt(gx: number, gy: number, gz: number): string {
  const px = C + (gx - gy) * TW
  const py = 84 + (gx + gy) * TH - gz * CH
  const top = `${px},${py - TH} ${px + TW},${py} ${px},${py + TH} ${px - TW},${py}`
  const left = `${px - TW},${py} ${px},${py + TH} ${px},${py + TH + CH} ${px - TW},${py + CH}`
  const right = `${px},${py + TH} ${px + TW},${py} ${px + TW},${py + CH} ${px},${py + TH + CH}`
  const s = `stroke="${STROKE}" stroke-width="1.3" stroke-linejoin="round"`
  return (
    `<polygon points="${left}" fill="${LEFT}" ${s}/>` +
    `<polygon points="${right}" fill="${RIGHT}" ${s}/>` +
    `<polygon points="${top}" fill="${TOP}" ${s}/>`
  )
}

/** A 3D stack from voxel coords [gx, gy, gz]. Painter-ordered back-to-front. */
export function isoStack(cells: [number, number, number][]): string {
  const sorted = [...cells].sort((a, b) => a[0] + a[1] + a[2] - (b[0] + b[1] + b[2]) || a[2] - b[2])
  return wrap(sorted.map((c) => cubeAt(c[0], c[1], c[2])).join(''))
}

// ── Flat blocky figures (for rotation / reflection / assembly) ───────────────
const CS = 16 // cell size

function cellsRects(cells: [number, number][], ox: number, oy: number, fill: string, size = CS): string {
  return cells
    .map(
      ([r, c]) =>
        `<rect x="${ox + c * size}" y="${oy + r * size}" width="${size}" height="${size}" rx="1.5" fill="${fill}" stroke="${STROKE}" stroke-width="1.6"/>`,
    )
    .join('')
}

/** A blocky figure (cells = [row,col]) centred in the box, with an optional transform. */
export function poly(cells: [number, number][], transform = '', fill = FILL): string {
  const rows = cells.map((c) => c[0])
  const cols = cells.map((c) => c[1])
  const minR = Math.min(...rows)
  const maxR = Math.max(...rows)
  const minC = Math.min(...cols)
  const maxC = Math.max(...cols)
  const w = (maxC - minC + 1) * CS
  const h = (maxR - minR + 1) * CS
  const ox = C - w / 2 - minC * CS
  const oy = C - h / 2 - minR * CS
  const inner = cellsRects(cells, ox, oy, fill)
  return wrap(transform ? `<g transform="${transform}">${inner}</g>` : inner)
}

// Transform strings (about the box centre).
export const T = {
  rot90: `rotate(90 ${C} ${C})`,
  rot180: `rotate(180 ${C} ${C})`,
  rot270: `rotate(270 ${C} ${C})`,
  mirror: `translate(${VB} 0) scale(-1 1)`,
  mirrorRot90: `rotate(90 ${C} ${C}) translate(${VB} 0) scale(-1 1)`,
  reflectDiag: `translate(${C} ${C}) matrix(0 1 1 0 0 0) translate(-${C} -${C})`,
}

// ── Paper folding ────────────────────────────────────────────────────────────
const SQ = { x0: 12, y0: 12, w: 96 } // unfolded square bounds

function squareOutline(): string {
  return `<rect x="${SQ.x0}" y="${SQ.y0}" width="${SQ.w}" height="${SQ.w}" rx="3" fill="${PAPER}" stroke="${STROKE}" stroke-width="2"/>`
}

/** Unfolded square with punched holes. Hole positions are 0–1 within the square. */
export function holesSquare(holes: [number, number][]): string {
  const dots = holes
    .map(([u, v]) => `<circle cx="${SQ.x0 + u * SQ.w}" cy="${SQ.y0 + v * SQ.w}" r="6.5" fill="${STROKE}"/>`)
    .join('')
  return wrap(squareOutline() + dots)
}

/** Prompt for a fold: shows fold axes (dashed), a fold arrow, and the punched hole. */
export function foldPrompt(holes: [number, number][], axes: ('v' | 'h')[]): string {
  const mid = SQ.x0 + SQ.w / 2
  const lines = axes
    .map((a) =>
      a === 'v'
        ? `<line x1="${mid}" y1="${SQ.y0}" x2="${mid}" y2="${SQ.y0 + SQ.w}" stroke="${RIGHT}" stroke-width="2" stroke-dasharray="4 3"/>`
        : `<line x1="${SQ.x0}" y1="${mid}" x2="${SQ.x0 + SQ.w}" y2="${mid}" stroke="${RIGHT}" stroke-width="2" stroke-dasharray="4 3"/>`,
    )
    .join('')
  const dots = holes
    .map(([u, v]) => `<circle cx="${SQ.x0 + u * SQ.w}" cy="${SQ.y0 + v * SQ.w}" r="6.5" fill="${STROKE}"/>`)
    .join('')
  return wrap(squareOutline() + lines + dots)
}

/** Prompt for the reflection item: the figure plus the dashed diagonal mirror axis. */
export function reflectPrompt(cells: [number, number][]): string {
  const rows = cells.map((c) => c[0])
  const cols = cells.map((c) => c[1])
  const w = (Math.max(...cols) - Math.min(...cols) + 1) * CS
  const h = (Math.max(...rows) - Math.min(...rows) + 1) * CS
  const ox = C - w / 2 - Math.min(...cols) * CS
  const oy = C - h / 2 - Math.min(...rows) * CS
  const diag = `<line x1="14" y1="14" x2="${VB - 14}" y2="${VB - 14}" stroke="${RIGHT}" stroke-width="2" stroke-dasharray="4 3"/>`
  return wrap(cellsRects(cells, ox, oy, FILL) + diag)
}

// ── Cube nets (arrangements of 6 unit squares) ───────────────────────────────
export function net(cells: [number, number][]): string {
  const rows = cells.map((c) => c[0])
  const cols = cells.map((c) => c[1])
  const w = (Math.max(...cols) - Math.min(...cols) + 1) * 18
  const h = (Math.max(...rows) - Math.min(...rows) + 1) * 18
  const ox = C - w / 2 - Math.min(...cols) * 18
  const oy = C - h / 2 - Math.min(...rows) * 18
  return wrap(cellsRects(cells, ox, oy, PAPER, 18))
}

// ── Assembly: a 4×4 board with a dashed missing region (the gap to fill) ─────
export function boardWithGap(gap: [number, number][]): string {
  const gapSet = new Set(gap.map(([r, c]) => `${r},${c}`))
  const present: [number, number][] = []
  for (let r = 0; r < 4; r++) for (let c = 0; c < 4; c++) if (!gapSet.has(`${r},${c}`)) present.push([r, c])
  const ox = C - (4 * CS) / 2
  const oy = C - (4 * CS) / 2
  const gaps = gap
    .map(
      ([r, c]) =>
        `<rect x="${ox + c * CS}" y="${oy + r * CS}" width="${CS}" height="${CS}" rx="1.5" fill="none" stroke="${STROKE}" stroke-width="1.6" stroke-dasharray="4 3"/>`,
    )
    .join('')
  return wrap(cellsRects(present, ox, oy, FILL) + gaps)
}

/** A standalone candidate piece (cells), centred. */
export function piece(cells: [number, number][]): string {
  return poly(cells, '', FILL)
}

// ── Regular polygon (for the symmetry item) ──────────────────────────────────
export function regularPolygon(n: number): string {
  const r = 42
  const pts: string[] = []
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (i * 2 * Math.PI) / n
    pts.push(`${(C + r * Math.cos(a)).toFixed(1)},${(C + r * Math.sin(a)).toFixed(1)}`)
  }
  return wrap(`<polygon points="${pts.join(' ')}" fill="${TOP}" stroke="${STROKE}" stroke-width="2.4" stroke-linejoin="round"/>`)
}
